// planb64 -- compile an IPv6 forwarding table into a canonical minimal
// interval image and answer longest-prefix-match queries from that image.
//
//   planb64 build FIB IMAGE
//   planb64 lookup IMAGE TRACE scalar
//   planb64 lookup IMAGE TRACE batch BATCH_SIZE
//
// The image is the minimal change-point (interval) representation of the
// longest-prefix-match function over the 64 upper address bits of an IPv6
// address.  Every FIB prefix is normalised (host bits cleared); the winner
// for a key is the normalised prefix with the greatest length.  The image is
// self-contained: the lookup path never sees the original FIB.

#include <arpa/inet.h>

#include <algorithm>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <fstream>
#include <queue>
#include <stdexcept>
#include <string>
#include <string_view>
#include <vector>

namespace {

// ---------------------------------------------------------------- limits --

constexpr uint64_t kMaxFibRecords = 200000;
constexpr uint64_t kMaxTraceRecords = 1000000;
constexpr size_t kMaxLineBytes = 256;
constexpr uint64_t kMaxImageRows = 400001;
constexpr uint64_t kMaxPrefixLength = 64;
constexpr uint64_t kMaxNextHop = 4294967295ULL;

// ------------------------------------------------------------ diagnostics --

[[noreturn]] void fail(const std::string& message) {
    throw std::runtime_error(message);
}

// ------------------------------------------------------------ text helpers --

constexpr bool is_space(char c) {
    return c == ' ' || c == '\t' || c == '\r' || c == '\v' || c == '\f';
}

constexpr bool is_digit(char c) { return c >= '0' && c <= '9'; }

constexpr bool is_lower_hex(char c) {
    return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f');
}

// Parse an unsigned decimal field.  Only ASCII digits are accepted, leading
// zeros are allowed, and the value must not exceed `max`.
bool parse_decimal(const char *begin, const char *end, uint64_t max,
                   uint64_t *out) {
    if (begin >= end) return false;
    uint64_t value = 0;
    for (const char *p = begin; p != end; ++p) {
        if (!is_digit(*p)) return false;
        const uint64_t digit = static_cast<uint64_t>(*p - '0');
        if (value > (max - digit) / 10) return false;
        value = value * 10 + digit;
    }
    *out = value;
    return true;
}

// Parse a canonical (unpadded) decimal field: digits only, no leading zero
// unless the value is exactly "0".
bool parse_canonical_decimal(const char *begin, const char *end, uint64_t max,
                             uint64_t *out) {
    if (begin >= end) return false;
    if (end - begin > 1 && *begin == '0') return false;
    return parse_decimal(begin, end, max, out);
}

// Append the decimal representation of `value` to `buf`; returns the length.
size_t format_decimal(char *buf, uint64_t value) {
    char tmp[24];
    size_t n = 0;
    do {
        tmp[n++] = static_cast<char>('0' + (value % 10));
        value /= 10;
    } while (value != 0);
    for (size_t i = 0; i < n; ++i) buf[i] = tmp[n - 1 - i];
    return n;
}

// Append the decimal representation of `value` (possibly negative) to `buf`.
size_t format_signed(char *buf, int64_t value) {
    if (value < 0) {
        buf[0] = '-';
        const uint64_t magnitude =
            static_cast<uint64_t>(-(value + 1)) + 1u;  // safe for INT64_MIN
        return 1 + format_decimal(buf + 1, magnitude);
    }
    return format_decimal(buf, static_cast<uint64_t>(value));
}

// Parse an IPv6 address (inet_pton syntax) and return its upper 64 bits.
bool parse_ipv6(const char *begin, const char *end, uint64_t *key) {
    const size_t len = static_cast<size_t>(end - begin);
    if (len == 0 || len >= 64) return false;
    char text[64];
    std::memcpy(text, begin, len);
    text[len] = '\0';
    unsigned char bytes[16];
    if (inet_pton(AF_INET6, text, bytes) != 1) return false;
    uint64_t value = 0;
    for (int i = 0; i < 8; ++i) value = (value << 8) | bytes[i];
    *key = value;
    return true;
}

// Clear the host bits of a prefix of the given length.
inline uint64_t normalize(uint64_t key, uint64_t length) {
    if (length == 0) return 0;
    return key & (~uint64_t(0) << (64 - length));
}

// --------------------------------------------------------------- records --

struct Prefix {
    uint64_t key;    // first covered key
    uint64_t last;   // last covered key
    uint64_t length; // prefix length
    uint64_t hop;    // next hop
};

struct Row {
    uint64_t start;
    int64_t hop;
    int64_t length;
};

// ------------------------------------------------------------------- I/O --

std::string read_whole_file(const std::string &path) {
    std::FILE *file = std::fopen(path.c_str(), "rb");
    if (file == nullptr) fail("cannot open file: " + path);
    std::string data;
    char buffer[65536];
    for (;;) {
        const size_t got = std::fread(buffer, 1, sizeof buffer, file);
        data.append(buffer, got);
        if (got < sizeof buffer) break;
    }
    const bool bad = std::ferror(file) != 0;
    std::fclose(file);
    if (bad) fail("read error: " + path);
    return data;
}

// ------------------------------------------------------------ FIB parsing --

void parse_fib_record(const std::string &line, Prefix *out) {
    const char *p = line.data();
    const char *const end = p + line.size();

    while (p < end && is_space(*p)) ++p;
    const char *first = p;
    while (p < end && !is_space(*p)) ++p;
    const char *first_end = p;
    if (first == first_end) fail("fib: empty record");

    while (p < end && is_space(*p)) ++p;
    const char *second = p;
    while (p < end && !is_space(*p)) ++p;
    const char *second_end = p;
    if (second == second_end) fail("fib: missing next hop");

    while (p < end && is_space(*p)) ++p;
    if (p != end) fail("fib: extra tokens in record");

    const char *slash =
        static_cast<const char *>(std::memchr(first, '/', static_cast<size_t>(first_end - first)));
    if (slash == nullptr) fail("fib: missing prefix length");

    uint64_t length = 0;
    if (!parse_decimal(slash + 1, first_end, kMaxPrefixLength, &length))
        fail("fib: invalid prefix length");

    uint64_t key = 0;
    if (!parse_ipv6(first, slash, &key)) fail("fib: invalid IPv6 address");

    uint64_t hop = 0;
    if (!parse_decimal(second, second_end, kMaxNextHop, &hop))
        fail("fib: invalid next hop");

    out->length = length;
    out->key = normalize(key, length);
    out->hop = hop;
    // The covered range is [key, key + 2^(64-length)); for length 0 the whole
    // 64 bit space is covered, which is expressed with last == UINT64_MAX.
    if (length == 0) {
        out->last = UINT64_MAX;
    } else {
        const uint64_t span = uint64_t(1) << (64 - length);
        out->last = out->key + span - 1;
    }
}

std::vector<Prefix> read_fib(const std::string &path) {
    std::ifstream in(path, std::ios::in | std::ios::binary);
    if (!in) fail("cannot open file: " + path);
    std::vector<Prefix> prefixes;
    std::string line;
    while (std::getline(in, line)) {
        if (line.size() > kMaxLineBytes) fail("fib: line too long");
        bool blank = true;
        for (char c : line) {
            if (!is_space(c)) {
                blank = false;
                break;
            }
        }
        if (blank) continue;
        Prefix prefix;
        parse_fib_record(line, &prefix);
        prefixes.push_back(prefix);
        if (prefixes.size() > kMaxFibRecords) fail("fib: too many records");
    }
    if (in.bad()) fail("read error: " + path);
    return prefixes;
}

// ------------------------------------------------------- interval compile --

std::vector<Row> compile_intervals(std::vector<Prefix> *prefixes) {
    std::sort(prefixes->begin(), prefixes->end(),
              [](const Prefix &a, const Prefix &b) {
                  if (a.key != b.key) return a.key < b.key;
                  return a.length < b.length;
              });
    for (size_t i = 1; i < prefixes->size(); ++i) {
        const Prefix &prev = (*prefixes)[i - 1];
        const Prefix &cur = (*prefixes)[i];
        if (prev.key == cur.key && prev.length == cur.length)
            fail("fib: duplicate prefix");
    }

    // Candidate change points: every prefix start and every prefix end.
    std::vector<uint64_t> points;
    points.reserve(prefixes->size() * 2 + 1);
    points.push_back(0);
    for (const Prefix &prefix : *prefixes) {
        points.push_back(prefix.key);
        if (prefix.last != UINT64_MAX) points.push_back(prefix.last + 1);
    }
    std::sort(points.begin(), points.end());
    points.erase(std::unique(points.begin(), points.end()), points.end());

    struct Entry {
        uint64_t length;
        uint64_t last;
        uint64_t hop;
    };
    struct ByLength {
        bool operator()(const Entry &a, const Entry &b) const {
            return a.length < b.length;  // longest prefix wins
        }
    };
    std::priority_queue<Entry, std::vector<Entry>, ByLength> active;

    std::vector<Row> rows;
    rows.reserve(points.size());
    size_t next = 0;
    bool have_previous = false;
    int64_t previous_hop = 0;
    int64_t previous_length = 0;

    for (uint64_t point : points) {
        while (next < prefixes->size() && (*prefixes)[next].key <= point) {
            const Prefix &prefix = (*prefixes)[next];
            active.push(Entry{prefix.length, prefix.last, prefix.hop});
            ++next;
        }
        while (!active.empty() && active.top().last < point) active.pop();

        int64_t hop = -1;
        int64_t length = -1;
        if (!active.empty()) {
            hop = static_cast<int64_t>(active.top().hop);
            length = static_cast<int64_t>(active.top().length);
        }
        if (!have_previous || hop != previous_hop || length != previous_length) {
            rows.push_back(Row{point, hop, length});
            if (rows.size() > kMaxImageRows) fail("image: too many rows");
            previous_hop = hop;
            previous_length = length;
            have_previous = true;
        }
    }

    if (rows.empty()) rows.push_back(Row{0, -1, -1});
    return rows;
}

// ------------------------------------------------------------ image output --

void write_image(const std::string &path, const std::vector<Row> &rows) {
    std::string text;
    text.reserve(rows.size() * 32 + 32);
    text += "PLANB64 1\n";
    text += std::to_string(rows.size());
    text += '\n';
    char buffer[64];
    for (const Row &row : rows) {
        size_t n = 0;
        for (int i = 15; i >= 0; --i) {
            const unsigned digit =
                static_cast<unsigned>((row.start >> (4 * i)) & 0xFULL);
            buffer[n++] = "0123456789abcdef"[digit];
        }
        buffer[n++] = ' ';
        n += format_signed(buffer + n, row.hop);
        buffer[n++] = ' ';
        n += format_signed(buffer + n, row.length);
        buffer[n++] = '\n';
        text.append(buffer, n);
    }

    std::FILE *file = std::fopen(path.c_str(), "wb");
    if (file == nullptr) fail("cannot open output file: " + path);
    const size_t written = std::fwrite(text.data(), 1, text.size(), file);
    const bool bad = written != text.size();
    if (std::fclose(file) != 0 || bad) fail("write error: " + path);
}

// ------------------------------------------------------------ image input --

// Parse one image row: "<16 hex digits> <next hop> <prefix length>".
void parse_image_row(std::string_view line, Row *out) {
    if (line.size() < 20) fail("image: malformed row");
    if (line[16] != ' ') fail("image: malformed row");
    for (size_t i = 0; i < 16; ++i) {
        if (!is_lower_hex(line[i])) fail("image: invalid start key");
    }
    uint64_t start = 0;
    for (size_t i = 0; i < 16; ++i) {
        const char c = line[i];
        unsigned digit = 0;
        if (c >= '0' && c <= '9') {
            digit = static_cast<unsigned>(c - '0');
        } else {
            digit = static_cast<unsigned>(c - 'a') + 10u;
        }
        start = (start << 4) | digit;
    }

    const size_t second = line.find(' ', 17);
    if (second == std::string_view::npos) fail("image: malformed row");
    const std::string_view hop_field = line.substr(17, second - 17);
    const std::string_view length_field = line.substr(second + 1);
    if (length_field.find(' ') != std::string_view::npos)
        fail("image: malformed row");

    bool no_match = false;
    int64_t hop = 0;
    int64_t length = 0;
    if (hop_field == "-1") {
        if (length_field != "-1") fail("image: one sided no-match row");
        no_match = true;
    } else if (length_field == "-1") {
        fail("image: one sided no-match row");
    } else {
        uint64_t hop_value = 0;
        if (!parse_canonical_decimal(hop_field.data(),
                                     hop_field.data() + hop_field.size(),
                                     kMaxNextHop, &hop_value))
            fail("image: invalid next hop");
        uint64_t length_value = 0;
        if (!parse_canonical_decimal(length_field.data(),
                                     length_field.data() + length_field.size(),
                                     kMaxPrefixLength, &length_value))
            fail("image: invalid prefix length");
        hop = static_cast<int64_t>(hop_value);
        length = static_cast<int64_t>(length_value);
    }
    (void)no_match;
    out->start = start;
    out->hop = hop;
    out->length = length;
}

std::vector<Row> read_image(const std::string &path) {
    const std::string data = read_whole_file(path);
    if (data.empty()) fail("image: empty file");
    if (data.back() != '\n') fail("image: missing final newline");

    size_t position = 0;
    auto next_line = [&](std::string_view *line) -> bool {
        if (position >= data.size()) return false;
        const size_t eol = data.find('\n', position);
        if (eol == std::string::npos) {
            *line = std::string_view(data.data() + position,
                                     data.size() - position);
            position = data.size();
        } else {
            *line = std::string_view(data.data() + position, eol - position);
            position = eol + 1;
        }
        return true;
    };

    std::string_view line;
    if (!next_line(&line)) fail("image: missing header");
    if (line != "PLANB64 1") fail("image: bad header");

    if (!next_line(&line)) fail("image: missing row count");
    uint64_t count = 0;
    if (!parse_canonical_decimal(line.data(), line.data() + line.size(),
                                 kMaxImageRows, &count))
        fail("image: bad row count");
    if (count < 1) fail("image: bad row count");

    std::vector<Row> rows;
    rows.reserve(static_cast<size_t>(count));
    while (next_line(&line)) {
        if (line.empty()) fail("image: blank line");
        if (rows.size() >= count) fail("image: extra records");
        Row row;
        parse_image_row(line, &row);
        rows.push_back(row);
    }
    if (rows.size() != count) fail("image: row count mismatch");
    if (rows.empty()) fail("image: bad row count");
    if (rows[0].start != 0) fail("image: first key is not zero");
    for (size_t i = 1; i < rows.size(); ++i) {
        if (rows[i].start <= rows[i - 1].start)
            fail("image: rows are not strictly increasing");
        if (rows[i].hop == rows[i - 1].hop && rows[i].length == rows[i - 1].length)
            fail("image: adjacent rows carry the same pair");
    }
    return rows;
}

// ----------------------------------------------------------- lookup index --

// A two level index: the top 16 bits of the key select a bucket, and the
// rows that start inside the bucket are searched with a binary search.
class Index {
  public:
    explicit Index(std::vector<Row> rows) : rows_(std::move(rows)) {
        bucket_first_.resize(kBuckets + 1);
        size_t index = 0;
        for (uint32_t bucket = 0; bucket <= kBuckets; ++bucket) {
            const uint64_t edge =
                (bucket == kBuckets) ? 0 : (static_cast<uint64_t>(bucket) << 48);
            while (index < rows_.size() && rows_[index].start < edge) ++index;
            bucket_first_[bucket] = static_cast<uint32_t>(index);
        }
    }

    const Row &find(uint64_t key) const {
        const uint32_t bucket = static_cast<uint32_t>(key >> 48);
        uint32_t low = bucket_first_[bucket];
        uint32_t high = bucket_first_[bucket + 1];
        // Find the first row in [low, high) whose start is greater than key.
        while (low < high) {
            const uint32_t middle = low + (high - low) / 2;
            if (rows_[middle].start <= key) {
                low = middle + 1;
            } else {
                high = middle;
            }
        }
        if (low == 0) return rows_[0];
        return rows_[low - 1];
    }

  private:
    static constexpr uint32_t kBuckets = 1u << 16;
    std::vector<Row> rows_;
    std::vector<uint32_t> bucket_first_;
};

// ---------------------------------------------------------- trace parsing --

std::vector<uint64_t> read_trace(const std::string &path) {
    std::ifstream in(path, std::ios::in | std::ios::binary);
    if (!in) fail("cannot open file: " + path);
    std::vector<uint64_t> keys;
    std::string line;
    while (std::getline(in, line)) {
        if (line.size() > kMaxLineBytes) fail("trace: line too long");
        const char *p = line.data();
        const char *const end = p + line.size();
        while (p < end && is_space(*p)) ++p;
        const char *token = p;
        while (p < end && !is_space(*p)) ++p;
        if (token == p) continue;  // blank line
        const char *token_end = p;
        while (p < end && is_space(*p)) ++p;
        if (p != end) fail("trace: extra tokens on line");
        uint64_t key = 0;
        if (!parse_ipv6(token, token_end, &key)) fail("trace: invalid IPv6 address");
        keys.push_back(key);
        if (keys.size() > kMaxTraceRecords) fail("trace: too many records");
    }
    if (in.bad()) fail("read error: " + path);
    return keys;
}

// ------------------------------------------------------------- batch size --

uint64_t parse_batch_size(const std::string &text) {
    if (text.empty()) fail("batch: invalid batch size");
    uint64_t value = 0;
    for (char c : text) {
        if (!is_digit(c)) fail("batch: invalid batch size");
        const uint64_t digit = static_cast<uint64_t>(c - '0');
        if (value > (256 - digit) / 10) fail("batch: invalid batch size");
        value = value * 10 + digit;
        if (value > 256) fail("batch: invalid batch size");
    }
    if (value < 1 || value > 256) fail("batch: invalid batch size");
    return value;
}

// -------------------------------------------------------------- commands --

void command_build(const std::string &fib_path, const std::string &image_path) {
    std::vector<Prefix> prefixes = read_fib(fib_path);
    std::vector<Row> rows = compile_intervals(&prefixes);
    write_image(image_path, rows);
}

void command_lookup(const std::string &image_path, const std::string &trace_path,
                    uint64_t batch_size) {
    Index index(read_image(image_path));
    const std::vector<uint64_t> keys = read_trace(trace_path);

    std::string out;
    out.reserve(1u << 20);
    char buffer[64];
    size_t offset = 0;
    const size_t total = keys.size();
    for (size_t i = 0; i < total; ++i) {
        // The batch size only groups the work; the semantics are identical.
        if (batch_size != 0 && (i % batch_size) == 0) {
            // start of a new batch
        }
        const Row &row = index.find(keys[i]);
        size_t n = 0;
        n += format_signed(buffer + n, row.hop);
        buffer[n++] = ' ';
        n += format_signed(buffer + n, row.length);
        buffer[n++] = '\n';
        out.append(buffer, n);
        if (out.size() >= (1u << 20)) {
            if (std::fwrite(out.data(), 1, out.size(), stdout) != out.size())
                fail("write error");
            out.clear();
        }
        ++offset;
    }
    (void)offset;
    if (!out.empty()) {
        if (std::fwrite(out.data(), 1, out.size(), stdout) != out.size())
            fail("write error");
    }
    if (std::fflush(stdout) != 0) fail("write error");
}

}  // namespace

int main(int argc, char **argv) {
    try {
        if (argc >= 2 && std::strcmp(argv[1], "build") == 0) {
            if (argc != 4) fail("usage: planb64 build FIB IMAGE");
            command_build(argv[2], argv[3]);
            return 0;
        }
        if (argc >= 2 && std::strcmp(argv[1], "lookup") == 0) {
            if (argc == 5) {
                if (std::strcmp(argv[4], "scalar") != 0)
                    fail("usage: planb64 lookup IMAGE TRACE scalar");
                command_lookup(argv[2], argv[3], 0);
                return 0;
            }
            if (argc == 6) {
                if (std::strcmp(argv[4], "batch") != 0)
                    fail("usage: planb64 lookup IMAGE TRACE batch BATCH_SIZE");
                command_lookup(argv[2], argv[3], parse_batch_size(argv[5]));
                return 0;
            }
            fail("usage: planb64 lookup IMAGE TRACE scalar|batch BATCH_SIZE");
        }
        fail("usage: planb64 build FIB IMAGE | "
             "planb64 lookup IMAGE TRACE scalar | "
             "planb64 lookup IMAGE TRACE batch BATCH_SIZE");
    } catch (const std::exception &error) {
        std::fprintf(stderr, "ERROR: %s\n", error.what());
        return 2;
    } catch (...) {
        std::fprintf(stderr, "ERROR: unknown failure\n");
        return 2;
    }
}
